/// Translate only known product enum values, never arbitrary endpoint or profile names.
pub fn label(value: &str) -> &str {
    let key = match value {
        "follow_system_default" => "Follow system default",
        "pinned" => "Pinned output",
        "headphone" => "Headphones",
        "built_in_compact_speaker" => "Compact speakers",
        "speaker" => "Speakers",
        "unknown" => "Unknown",
        "stable_id" => "Stable ID",
        "display_name" => "Display name",
        "coreaudio_process_tap" | "pulse_server" | "wasapi_process_loopback" => {
            "Native process tap"
        }
        "multi_device_mixer" => "Mixer controls",
        "mixer_assignments" => "Mixer channels",
        "device_stream" => "Device stream",
        "selected_processes" => "Selected applications",
        "system_playback_excluding_maris" => "System playback",
        "explicit_endpoint" => "Explicit endpoint",
        "select_output" => "Select output",
        "select_applications" => "Select applications",
        "stop" => "Stop",
        "balanced" => "Balanced",
        "warm" => "Warm",
        "clear" => "Clear",
        "soft" => "Soft",
        _ => return value,
    };
    super::text(key)
}

pub fn preset_key<'a>(id: &str, original: &'a str) -> &'a str {
    if let Some(scene) = crate::presets::scenes::find(id) {
        return scene.name;
    }
    match id {
        "natural" => "Natural",
        "warm" => "Warm",
        "vocal" => "Vocal",
        "detail" => "Detail",
        "soft" => "Soft",
        "night" => "Night",
        "flat" | "eqmac:flat" => "Flat",
        "bass" => "Bass",
        "clarity" => "Clarity",
        "custom" => "Custom",
        _ => original,
    }
}
pub fn preset_name<'a>(id: &str, original: &'a str) -> &'a str {
    if crate::presets::scenes::find(id).is_some()
        || id.starts_with("eqmac:")
        || crate::dsp::profile::PRESETS.contains(&id)
        || crate::dsp::music::PRESETS.contains(&id)
        || id == "custom"
    {
        super::text(preset_key(id, original))
    } else {
        original
    }
}
